-- Group 7, public visibility, Moscow time. Stable IDs prevent duplicate imports.
begin;
on conflict (id) do nothing;
commit;

select count(*) as imported_of_16,
count(*) filter(where space='shared' and not deleted) as visible_shared_of_16
from public.planner_events
where id between 'b26e1109-2026-4000-8000-000000000001'::uuid
and 'b26e1109-2026-4000-8000-000000000016'::uuid;
